defmodule ExironWeb.Endpoint do
  use Phoenix.Endpoint, otp_app: :exiron

  @session_options [
    store: :cookie,
    key: "_exiron_key",
    signing_salt: "tjbLn9LX",
    encryption_salt: "aX7kMq2p",
    same_site: "Lax"
  ]

  socket "/live", Phoenix.LiveView.Socket,
    websocket: [connect_info: [session: @session_options]],
    longpoll: [connect_info: [session: @session_options]]

  # Serve at "/" the static files from "priv/static" directory.
  #
  # When code reloading is disabled (e.g., in production),
  # the `gzip` option is enabled to serve compressed
  # static files generated by running `phx.digest`.
  plug Plug.Static,
    at: "/",
    from: :exiron,
    gzip: not code_reloading?,
    only: ExironWeb.static_paths(),
    raise_on_missing_only: code_reloading?

  # Code reloading can be explicitly enabled under the
  # :code_reloader configuration of your endpoint.
  if code_reloading? do
    socket "/phoenix/live_reload/socket", Phoenix.LiveReloader.Socket
    plug Phoenix.LiveReloader
    plug Phoenix.CodeReloader
  end

  plug Phoenix.LiveDashboard.RequestLogger,
    param_key: "request_logger",
    cookie_key: "request_logger"

  plug Plug.RequestId
  plug Plug.Telemetry, event_prefix: [:phoenix, :endpoint], log: false

  # Method override must run before the router selects a route. Only decode the
  # small URL-encoded browser forms it needs here; large API JSON bodies are
  # parsed later, after route-specific rate limiting and authentication.
  plug ExironWeb.Plugs.TrustedProxy
  plug ExironWeb.Plugs.TrustedSSL
  plug ExironWeb.Plugs.LoginRateLimit
  plug ExironWeb.Plugs.BrowserFormParser
  plug Plug.MethodOverride
  plug Plug.Head
  plug ExironWeb.Session, @session_options
  plug ExironWeb.Router
end
